def fuse_all(nodes):
    while True:
        cands = [(a, b) for a, b in pairs(nodes)
                 if can_fuse(a, b)]
        if not cands:
            break
        cands.sort(key=score_fusion, reverse=True)
        changed = False
        for a, b in cands:
            if still_legal(a, b, nodes):
                nodes = merge(nodes, a, b)
                changed = True
        if not changed:
            break
    return nodes
